import java.time.Duration

// :core is plain Kotlin/JVM with no android.* dependency: protocol,
// crypto, pairing, sync and event reduction, all testable on the JVM.
plugins {
    alias(libs.plugins.kotlin.jvm)
}

kotlin {
    jvmToolchain(17)
}

sourceSets {
    main {
        // Generated by `buf generate` in android/, see buf.gen.yaml.
        java.srcDir("src/main/gen")
        kotlin.srcDir("src/main/gen")
    }
}

val repoRoot = rootProject.file("..")
val coreOutRoot = repoRoot.resolve("build/core")
val corebindAar = coreOutRoot.resolve("android/corebind.aar")
val hostOs = System.getProperty("os.name").lowercase()
val corebindHostDir = coreOutRoot.resolve("android-host")
val corebindHostLib = corebindHostDir.resolve(if (hostOs.contains("mac")) "libgojni.dylib" else "libgojni.so")
val coreBuildInputs = fileTree(repoRoot) {
    include("clientcore/**/*.go", "clientcore/go.mod", "clientcore/go.sum", "proto/**/*.proto", "scripts/core/build.sh")
    exclude("clientcore/**/*_test.go")
}
val buildCorebindAar by tasks.registering(Exec::class) {
    workingDir = repoRoot
    inputs.files(coreBuildInputs).withPathSensitivity(PathSensitivity.RELATIVE)
    outputs.file(corebindAar)
    commandLine("bash", repoRoot.resolve("scripts/core/build.sh").absolutePath, "android")
}
val buildCorebindHost by tasks.registering(Exec::class) {
    workingDir = repoRoot
    inputs.files(coreBuildInputs).withPathSensitivity(PathSensitivity.RELATIVE)
    outputs.file(corebindHostLib)
    commandLine("bash", repoRoot.resolve("scripts/core/build.sh").absolutePath, "android-host")
}
val corebindJarDir = layout.buildDirectory.dir("corebind-jar")
val corebindClassesJar = corebindJarDir.map { it.file("classes.jar") }
val extractCorebindJar by tasks.registering(Copy::class) {
    dependsOn(buildCorebindAar)
    from(zipTree(corebindAar)) { include("classes.jar") }
    into(corebindJarDir)
}

dependencies {
    compileOnly(files(corebindClassesJar) { builtBy(extractCorebindJar) })
    api(libs.protobuf.javalite)
    // connect-kotlin declares moshi-kotlin, the reflective adapter factory,
    // but reads its JSON with generated adapters, which need Moshi alone.
    // See LiteProtobuf.kt for why kotlin-reflect is kept out.
    api(libs.connect.okhttp) {
        exclude(group = "com.squareup.moshi", module = "moshi-kotlin")
        exclude(group = "org.jetbrains.kotlin", module = "kotlin-reflect")
    }
    runtimeOnly(libs.moshi)
    api(libs.okhttp)
    api(libs.coroutines.core)
    implementation(libs.bouncycastle)

    testImplementation(files(corebindClassesJar) { builtBy(extractCorebindJar) })
    testImplementation(libs.junit)
    testImplementation(libs.coroutines.test)
    api(libs.serialization.json)
}

// Build the two immutable Go fixtures together. Each test still owns its
// server, database and signing process; Gradle reuses only the executables.
val testFixtures = layout.buildDirectory.dir("test-fixtures")
val buildTestFixtures by tasks.registering(Exec::class) {
    workingDir = repoRoot
    inputs.files(fileTree(repoRoot) {
        include("go.mod", "go.sum", "internal/**/*.go", "internal/updater/policy.json", "gen/**/*.go")
        exclude("**/*_test.go")
    }).withPathSensitivity(PathSensitivity.RELATIVE)
    outputs.dir(testFixtures)
    commandLine("go", "build", "-o", testFixtures.get().asFile.absolutePath + "/",
        "./internal/testutil/relaytestserver", "./internal/testutil/securityfixture")
    onlyIf { System.getenv("PATH").orEmpty().split(File.pathSeparator).any { File(it, "go").canExecute() } }
}
tasks.test {
    timeout.set(Duration.ofMinutes(5))
    testLogging {
        events(
            org.gradle.api.tasks.testing.logging.TestLogEvent.STARTED,
            org.gradle.api.tasks.testing.logging.TestLogEvent.PASSED,
            org.gradle.api.tasks.testing.logging.TestLogEvent.FAILED,
            org.gradle.api.tasks.testing.logging.TestLogEvent.SKIPPED,
        )
        exceptionFormat = org.gradle.api.tasks.testing.logging.TestExceptionFormat.FULL
    }
    inputs.dir(rootProject.file("../testdata/transport")).withPathSensitivity(PathSensitivity.NONE)
    systemProperty("outcomeVectors", rootProject.file("../testdata/transport/outcomes.json").absolutePath)
    inputs.dir(rootProject.file("../i18n/messages")).withPathSensitivity(PathSensitivity.RELATIVE)
    // Classes own isolated relay processes; keep each class ordered and overlap
    // two classes so real network/backoff waits do not serialize the whole JVM suite.
    maxParallelForks = minOf(2, Runtime.getRuntime().availableProcessors())
    dependsOn(buildTestFixtures, buildCorebindHost)
    inputs.file(corebindHostLib).withPathSensitivity(PathSensitivity.RELATIVE)
    systemProperty("java.library.path", corebindHostDir.absolutePath)
    // A changed Go relay must rerun JVM integration tests even if Kotlin did not change.
    inputs.files(testFixtures).withPathSensitivity(PathSensitivity.RELATIVE)
    systemProperty("raSecurityFixture", testFixtures.get().file("securityfixture").asFile.absolutePath)
    systemProperty("raServer", testFixtures.get().file("relaytestserver").asFile.absolutePath)
    inputs.file(rootProject.file("../testdata/preview-plain.json")).withPathSensitivity(PathSensitivity.NONE)
    systemProperty("previewTableVectors", rootProject.file("../testdata/preview-plain.json").absolutePath)
    inputs.file(rootProject.file("../testdata/schedules/clients.json")).withPathSensitivity(PathSensitivity.NONE)
    systemProperty("scheduleClients", rootProject.file("../testdata/schedules/clients.json").absolutePath)
    systemProperty("vectors", rootProject.file("../internal/e2e/testdata/vectors.json").absolutePath)
    systemProperty("completionVectors",rootProject.file("../internal/deviceauth/testdata/revocation-v2.json").absolutePath)
    systemProperty("domainVectors", rootProject.file("../internal/deviceauth/testdata/domain-v3.json").absolutePath)
    systemProperty("v3Vectors", rootProject.file("../internal/e2e/testdata/v3-vectors.json").absolutePath)
    systemProperty("recoveryVectors", rootProject.file("../internal/deviceauth/testdata/recovery-v3.json").absolutePath)
    systemProperty("recoveryRemovedVectors", rootProject.file("../internal/deviceauth/testdata/recovery-removed-v3.json").absolutePath)
    systemProperty("chainVectors", rootProject.file("../internal/deviceauth/testdata/chain-v3.json").absolutePath)
    systemProperty("kotlinVectors", rootProject.file("../internal/e2e/testdata/kotlin-vectors.json").absolutePath)
    inputs.file(rootProject.file("../testdata/shared-files/blocks.json")).withPathSensitivity(PathSensitivity.NONE)
    systemProperty("sharedFileVectors", rootProject.file("../testdata/shared-files/blocks.json").absolutePath)
    // ./gradlew :core:test -PupdateVectors rewrites kotlin-vectors.json.
    if (project.hasProperty("updateVectors")) systemProperty("updateVectors", "1")
}
